import{_ as t}from"./chunks/ha-label-erstellen.DlZFuxLI.js";import{_ as s,o as n,c as a,a3 as r}from"./chunks/framework.BlfGB29P.js";const v=JSON.parse('{"title":"Client MQTT","description":"Transmettre en temps réel des valeurs sélectionnées de Home Assistant via MQTT et les piloter de manière ciblée.","frontmatter":{"title":"Client MQTT","description":"Transmettre en temps réel des valeurs sélectionnées de Home Assistant via MQTT et les piloter de manière ciblée."},"headers":[],"relativePath":"fr/projects/mqtt-client/index.md","filePath":"fr/projects/mqtt-client/index.md","lastUpdated":1794054216000}'),i={name:"fr/projects/mqtt-client/index.md"};function o(l,e,u,c,d,p){return n(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="mqtt-client-0-1-16" tabindex="-1">Client MQTT 0.1.30 <a class="header-anchor" href="#mqtt-client-0-1-16" aria-label="Permalink to &quot;Client MQTT 0.1.30 {#mqtt-client-0-1-16}&quot;">​</a></h1><p>Transmettre les états et attributs HA sélectionnés vers un broker MQTT externe. La version 0.1.30 donne la priorité aux retours de commande et ajoute un contrôle des états HA. Installez la mise à jour de l’application HA ; le script 0.1.27 peut rester.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/mqtt-client-v0.1.30" target="_blank" rel="noreferrer">Release 0.1.30</a></p><h2 id="enable-device-readings" tabindex="-1">Important : activer explicitement les mesures supplémentaires <a class="header-anchor" href="#enable-device-readings" aria-label="Permalink to &quot;Important : activer explicitement les mesures supplémentaires {#enable-device-readings}&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Important : activer explicitement les mesures supplémentaires</p><p><strong>Une étiquette seule n’active pas les mesures supplémentaires.</strong> Dans <strong>Transmission et TLS</strong>, cochez <strong>« Inclure automatiquement les mesures et valeurs de batterie du même appareil »</strong> (interface allemande : <strong>„Zugehörige Mess- und Batteriewerte desselben Geräts automatisch einbeziehen“</strong>), puis cliquez sur <strong>« Enregistrer et connecter »</strong>. Sans cette case, l’énergie, la tension, le courant et la puissance ne sont pas automatiquement ajoutés à l’interrupteur étiqueté. Les valeurs sélectionnées manuellement restent indépendantes de cette option.</p></div><p>Seuls les capteurs compatibles, activés dans HA et associés au même appareil HA sont inclus, s’ils existent. Aucune mesure absente de l’appareil n’est créée. <strong>« Vérifier les mesures associées »</strong> indique la détection et les motifs d’exclusion. Les états de commande sont prioritaires ; les mesures peuvent suivre avec un délai.</p><h2 id="javascript-vis2-helper" tabindex="-1">Pour VIS 2 en particulier : le script JavaScript ioBroker <a class="header-anchor" href="#javascript-vis2-helper" aria-label="Permalink to &quot;Pour VIS 2 en particulier : le script JavaScript ioBroker {#javascript-vis2-helper}&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Pour VIS 2 en particulier : le script JavaScript ioBroker</p><p>Le <strong>JavaScript fourni s’exécute dans l’adaptateur JavaScript ioBroker, pas dans Home Assistant</strong>. Il crée des points virtuels sous <code>0_userdata.0.ugso_mqtt</code> : <strong>un point par valeur pour l’affichage et la commande</strong>, même si MQTT utilise des topics <code>state</code> et <code>set</code> séparés. Les interrupteurs et valeurs de lampe compatibles disposent du canal de commande approprié ; les mesures restent en lecture seule. Les métadonnées HA adaptées déterminent les types, unités et rôles non ambigus. Une commande n’est confirmée qu’après un véritable retour HA.</p><p><strong>Vérifiez d’abord l’aperçu, puis choisissez <code>mode: &#39;apply&#39;</code>.</strong> L’aperçu crée uniquement les dossiers de base/points de sauvegarde manquants du script ; les points VIS-2 virtuels sont créés en mode application. <strong>setObject</strong> doit être autorisé dans les réglages de l’adaptateur pour leur création. Les valeurs existantes et rôles définis manuellement restent protégés. L’application HA est en <strong>0.1.30</strong>, le script actuel reste en <strong>0.1.27</strong> : cette différence est volontaire. Le transfert MQTT seul fonctionne aussi sans le script.</p></div><h2 id="nouveaute-0-1-30-identifiants-repliables" tabindex="-1">Nouveauté 0.1.30 : identifiants repliables <a class="header-anchor" href="#nouveaute-0-1-30-identifiants-repliables" aria-label="Permalink to &quot;Nouveauté 0.1.30 : identifiants repliables&quot;">​</a></h2><p>La section <strong>Identifiants</strong> dispose désormais d’un bouton pour la déplier ou la replier, également utilisable au clavier. Si le broker est configuré, l’adresse IP, le port, le nom d’utilisateur et le mot de passe restent repliés après chargement et enregistrement. Si des champs obligatoires manquent, la section s’ouvre pour les corriger. <strong>Transmission et TLS</strong>, <strong>Enregistrer et connecter</strong> et <strong>Valeurs actuellement transmises</strong> restent visibles. Les réglages et identifiants ne sont pas modifiés. La priorité de la version 0.1.29 et le script 0.1.27 sont conservés. L’utilisateur a confirmé le bon fonctionnement du retour de commande avec un délai d’environ une demi-seconde. La lampe Zigbee a également été testée avec succès : le retour d’état fonctionne et la luminosité suit HA à 100 %.</p><h2 id="nouveaute-0-1-29-etats-de-commande-avant-mesures" tabindex="-1">Nouveauté 0.1.29 : états de commande avant mesures <a class="header-anchor" href="#nouveaute-0-1-29-etats-de-commande-avant-mesures" aria-label="Permalink to &quot;Nouveauté 0.1.29 : états de commande avant mesures&quot;">​</a></h2><p><strong>Mettez l’application HA MQTT-Client à jour vers 0.1.29 ; le script ioBroker 0.1.27 reste inchangé.</strong> Les états de commande/contact et les retours des commandes sont prioritaires sur les mesures et ne subissent pas la pause de publication configurée. Une transmission déjà engagée se termine normalement ; entre les messages, les lots de mesures/attributs cèdent la priorité aux états urgents ou commandes. À partir de 32 événements en attente, des lots limités de capteurs regroupent les valeurs intermédiaires pour conserver le dernier état de chaque source. Les changements de commande ordinaires restent conservés. Un contrôle périodique lit les états HA réels même avec la connexion en direct active, selon le <code>poll_interval</code> existant (5 secondes par défaut). Les valeurs inchangées ne sont pas republiées. <strong>Übertragung und TLS</strong> et la pause de publication des mesures/attributs sont directement visibles ; les identifiants de connexion restent repliables séparément. La ligne d’état distingue la file (<strong>Wartend</strong>), les événements regroupés (<strong>Zusammengefasst</strong>), la dernière réception HA (<strong>HA-Eingang</strong>) et le compteur cumulatif (<strong>Gesendet</strong>). Les réglages et valeurs existants sont conservés. Pour vérifier, laissez le contrôle à 5 secondes et actionnez un relais non critique dans HA. Seul un retour HA réel entraîne <code>ack: true</code> ; la transmission au broker ne suffit pas. Vérifié localement ; la latence réelle chez l’utilisateur reste à confirmer.</p><p>Les interrupteurs sont reconnus par le domaine <code>switch.*</code>, sans classe d’appareil ni unité obligatoire. Les lampes utilisent <code>light.*</code>. La sélection automatique des mesures, lorsqu’elle est activée, reste limitée au même appareil HA. Les capteurs utilisent d’abord <code>device_class</code> ; si elle manque, les unités non ambiguës de <code>unit_of_measurement</code>, telles que W/kW/MW, V/mV/kV, A/mA et Wh/kWh/MWh, sont utilisées. Les classes existantes ne sont jamais remplacées ; des noms similaires ou un pourcentage ambigu ne suffisent pas. <strong>Vérifier les mesures associées</strong> (interface allemande : <strong>Zugehörige Messwerte prüfen</strong>) affiche un rapport en lecture seule des capteurs détectés et des motifs d’exclusion : association d’appareil absente, entité désactivée ou classe/unité inadaptée. Les mesures peuvent attendre derrière les états de commande. Les réglages, identifiants et valeurs existantes sont conservés.</p><h2 id="nouveaute-0-1-28-retours-ha-sans-surcharge-d-evenements-etrangers" tabindex="-1">Nouveauté 0.1.28 : retours HA sans surcharge d’événements étrangers <a class="header-anchor" href="#nouveaute-0-1-28-retours-ha-sans-surcharge-d-evenements-etrangers" aria-label="Permalink to &quot;Nouveauté 0.1.28 : retours HA sans surcharge d’événements étrangers&quot;">​</a></h2><p>Cette correction concerne <strong>l’application MQTT-Client dans Home Assistant</strong> : mettez-la à jour vers 0.1.28 et redémarrez l’application. Le script ioBroker 0.1.27 peut rester inchangé ; son seul remplacement ne corrige pas la réception des événements HA. Avec la sélection par étiquette, seuls les événements des entités sélectionnées et de leurs mesures du même appareil activées sont mis en file. Les événements du reste de HA ne peuvent plus remplir cette file. Après modification des étiquettes ou des affectations d’appareils, le client récupère des états HA récents. Les états en attente avec un ancien <code>last_updated</code> sont ignorés après resynchronisation ; les changements normalement ordonnés restent conservés. Le compteur de surcharge est cumulatif depuis le démarrage et signale toujours les débordements réels des événements sélectionnés. Le délai de publication configuré, les identifiants de connexion et les sélections sont conservés ; une première synchronisation importante peut encore durer. Après celle-ci, actionnez un relais non critique dans HA et vérifiez que MQTT et le point virtuel ioBroker suivent rapidement. La confirmation sur le système réel de l’utilisateur reste à faire.</p><h2 id="nouveaute-0-1-27-commandes-sans-retain" tabindex="-1">Nouveauté 0.1.27 : commandes sans retain <a class="header-anchor" href="#nouveaute-0-1-27-commandes-sans-retain" aria-label="Permalink to &quot;Nouveauté 0.1.27 : commandes sans retain&quot;">​</a></h2><p>Les commandes utilisent désormais l’API <code>sendMessage2Client</code> de l’adaptateur MQTT ioBroker avec <strong><code>retain: false</code></strong>. En mode serveur, une écriture normale dans un point MQTT <code>set</code> peut parvenir au client avec le drapeau RETAIN. Le client HA continue de refuser ces commandes afin de ne pas exécuter d’anciennes demandes à la reconnexion. Les réglages globaux du broker et les valeurs des points MQTT sont conservés. Le script vérifie le topic de commande par rapport au topic d’état via <code>native.topic</code>, sans déduire les chemins des identifiants d’objets. Dans VIS 2, commandez toujours le point virtuel sous <code>0_userdata.0.ugso_mqtt</code> avec <code>ack: false</code> et <code>mode: &#39;apply&#39;</code>. La ligne <code>Command handed to MQTT adapter (retain=false)</code> confirme uniquement la transmission à l’adaptateur ; un nouvel état HA doit confirmer l’exécution. La valeur brute du point MQTT <code>set</code> ne change pas nécessairement. Aucun nouvel essai automatique ; les erreurs ou l’absence de retour HA restent non confirmées. Remplacez le fichier complet du script en conservant vos réglages.</p><h2 id="nouveaute-0-1-26-creation-automatique-de-la-base" tabindex="-1">Nouveauté 0.1.26 : création automatique de la base <a class="header-anchor" href="#nouveaute-0-1-26-creation-automatique-de-la-base" aria-label="Permalink to &quot;Nouveauté 0.1.26 : création automatique de la base&quot;">​</a></h2><p>Les dossiers de base du script (<code>virtualRoot</code>, <code>aliasRoot</code>) et les deux points de sauvegarde (<code>virtualBackupId</code>, <code>backupId</code>) absents sont désormais créés automatiquement au démarrage dans <strong>tous les modes</strong>, y compris <code>preview</code> et <code>restore</code>. Les dossiers, sauvegardes, valeurs et rôles manuels existants ne sont pas écrasés. Les nouveaux journaux contiennent des structures vides valides. Autorisez <code>setObject</code> dans l’instance JavaScript même pour l’aperçu. Les autorisations manquantes et les chemins incompatibles sont signalés comme erreurs. L’aperçu ne crée aucun point VIS 2 commandable et ne modifie ni les rôles MQTT ni les valeurs des appareils ; utilisez <code>mode: &#39;apply&#39;</code> après vérification pour ces opérations. Le traitement événementiel de la version 0.1.25 est conservé.</p><h2 id="points-vis-2-automatiques-depuis-0-1-24" tabindex="-1">Points VIS 2 automatiques depuis 0.1.24 <a class="header-anchor" href="#points-vis-2-automatiques-depuis-0-1-24" aria-label="Permalink to &quot;Points VIS 2 automatiques depuis 0.1.24&quot;">​</a></h2><p>Le script ioBroker combiné crée des points virtuels réunissant retour d’état et canal de commande. Il prend en charge les interrupteurs, valeurs Light et autres canaux numériques/listes/texte autorisés ; dates et mesures restent en lecture seule. Les valeurs MQTT d’origine, paramètres et alias existants sont conservés. Aperçu, sauvegarde automatique, contrôle des types/limites et protection contre les boucles sont inclus. Les avertissements pour les points optionnels absents sont corrigés. Préparé pour les API de l’adaptateur JavaScript <strong>10.4.10</strong> ; pas encore de nouvel essai dans une installation réelle.</p><p><a href="./iobroker-roles#vis2">Configuration et correspondances</a> · <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/mqtt-client-v0.1.24" target="_blank" rel="noreferrer">Version 0.1.24</a></p><h2 id="attribution-des-roles-iobroker-depuis-0-1-23" tabindex="-1">Attribution des rôles ioBroker depuis 0.1.23 <a class="header-anchor" href="#attribution-des-roles-iobroker-depuis-0-1-23" aria-label="Permalink to &quot;Attribution des rôles ioBroker depuis 0.1.23&quot;">​</a></h2><p>Un JavaScript optionnel attribue aux dates, horodatages et mesures non ambiguës des rôles ioBroker adaptés. Il comprend un aperçu, une sauvegarde préalable et une restauration contrôlée. Les valeurs existantes, identifiants de connexion et rôles spécifiques manuels sont conservés. Les mesures MQTT accessibles en écriture utilisent des alias en lecture seule. Les types, unités et classes incompatibles sont ignorés.</p><p><a href="./iobroker-roles">Installation et correspondances complètes HA → ioBroker</a> · <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/mqtt-client-v0.1.23" target="_blank" rel="noreferrer">Version 0.1.23</a></p><h2 id="nouveautes-de-la-version-0-1-22" tabindex="-1">Nouveautés de la version 0.1.22 <a class="header-anchor" href="#nouveautes-de-la-version-0-1-22" aria-label="Permalink to &quot;Nouveautés de la version 0.1.22&quot;">​</a></h2><p>La sélection par étiquette comprend désormais l’état, les métadonnées standard disponibles et les canaux de commande des entités pilotables prises en charge. Les interrupteurs reçoivent automatiquement <code>&lt;base&gt;/set</code> pour <code>ON</code>/<code>OFF</code> ; les nombres, listes de choix et boutons utilisent leurs commandes prises en charge. Aucune commande n’est envoyée lors de la configuration. Les commandes persistantes, vides ou invalides sont rejetées.</p><p>Les lampes ne reçoivent que les canaux correspondant aux fonctions déclarées par HA :</p><table tabindex="0"><thead><tr><th>Canal sous <code>&lt;base&gt;</code></th><th>Valeur et canal de commande</th></tr></thead><tbody><tr><td><code>brightness/state</code>, <code>brightness/set</code></td><td>Luminosité de 0 à 100 %</td></tr><tr><td><code>rgb_color/state</code>, <code>rgb_color/set</code></td><td>JSON <code>[255,128,0]</code>, composantes de 0 à 255</td></tr><tr><td><code>effect/state</code>, <code>effect/set</code></td><td>Nom figurant dans la liste d’effets déclarée</td></tr><tr><td><code>color_temp_kelvin/state</code>, <code>color_temp_kelvin/set</code></td><td>Kelvin entiers dans les limites déclarées</td></tr></tbody></table><p><code>&lt;base&gt;</code> est le topic existant sans <code>/state</code>. Les listes d’effets, modes de couleur et limites Kelvin sont des attributs en lecture seule. Les attributs HA sélectionnés manuellement conservent leur chemin et leur unité : <code>attribute/brightness</code> reste compris entre 0 et 255.</p><p>Dans <strong>Übertragung und TLS</strong> (Transmission et TLS), activez <strong>Zugehörige Mess- und Batteriewerte desselben Geräts automatisch einbeziehen</strong> pour inclure les mesures associées. <code>label_device_readings</code> vaut <code>false</code> par défaut. Les mesures prises en charge sont l’énergie, la tension, le courant, la puissance, la température, l’humidité, la batterie et un éventuel capteur de batterie faible. Seule l’identité de l’appareil HA est utilisée, jamais la similitude des noms. Aucun seuil n’est inventé. Ces capteurs supplémentaires n’ont pas de canal de commande.</p><p>Les métadonnées automatiques comprennent les noms, classes d’appareil, unités et classes d’état disponibles, ainsi que les choix et limites nécessaires. Les autres attributs restent sélectionnables manuellement. <code>device_class</code> est transmis comme métadonnée ; cela ne modifie pas automatiquement un rôle ioBroker tel que <code>date</code>.</p><p>La fenêtre des transmissions affiche aussi les attributs automatiques, valeurs Light et canaux de commande actifs avec leur origine. Le retrait d’une étiquette révoque les valeurs et commandes automatiques au prochain contrôle ; les commandes en attente sont revérifiées avant exécution. Les sélections manuelles et identifiants sont conservés. Les anciennes valeurs persistantes ne sont supprimées qu’avec le nettoyage confirmé des topics.</p><p>Vérification locale avec HA et broker simulés ; aucun nouvel essai sur appareil HA. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/mqtt-client-v0.1.22" target="_blank" rel="noreferrer">Version 0.1.22</a></p><h2 id="transmissions-actuelles" tabindex="-1">Transmissions actuelles <a class="header-anchor" href="#transmissions-actuelles" aria-label="Permalink to &quot;Transmissions actuelles&quot;">​</a></h2><p>Depuis <strong>0.1.21</strong>, seuls les identifiants de connexion se replient automatiquement. <strong>Übertragung und TLS</strong> (Transmission et TLS) reste accessible séparément. Les boutons <strong>Enregistrer et connecter</strong> et <strong>Transmissions actuelles</strong>, de même taille, restent visibles sur une même ligne.</p><p>Le second bouton ouvre une liste avec recherche et défilement de tous les états et attributs actuellement sélectionnés, y compris les états sélectionnés par une étiquette HA. Les états en double sont regroupés. L’origine est indiquée par un badge avec texte : <strong>Étiquette</strong> en bleu, <strong>Manuel</strong> en vert, <strong>Les deux</strong> en violet. Depuis 0.1.22, les attributs standard automatiques et les valeurs Light sont également affichés.</p><p>Chaque entrée affiche le nom, l’identifiant de l’entité, l’attribut éventuel, la valeur actuelle et le topic MQTT. Le dernier accusé de réception du broker comprend la date et la valeur envoyée ; les valeurs non confirmées sont signalées et les erreurs apparaissent séparément en rouge. L’accusé confirme l’acceptation par le broker, pas le traitement par ioBroker ou un appareil cible. La fenêtre ouverte s’actualise toutes les trois secondes ainsi qu’avec <strong>Actualiser</strong>. L’aperçu concerne la connexion en cours et se réinitialise à son redémarrage. Les paramètres et identifiants de connexion ne sont ni modifiés ni affichés dans cette liste. Vérifications locales : sélections manuelles et par étiquette, attributs, erreurs de confirmation et présentation mobile. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/mqtt-client-v0.1.21" target="_blank" rel="noreferrer">Version 0.1.21</a></p><p><strong>0.1.20 :</strong> Les paramètres de connexion sont repliables sous <strong>Zugangsdaten</strong> (Identifiants de connexion). La section reste ouverte pour la première configuration. Avec une adresse de broker enregistrée, elle se replie après le chargement et l’enregistrement réussi. Cliquez sur le titre pour la rouvrir. Les messages d’enregistrement et d’erreur restent visibles ; les paramètres et les identifiants de connexion sont conservés. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/mqtt-client-v0.1.20" target="_blank" rel="noreferrer">Version 0.1.20</a></p><p>La version <strong>0.1.19</strong> sépare également les lignes dans la liste des transmissions : le nom apparaît au-dessus du résumé de l’état, des attributs sélectionnés et de la commande de retour. <strong>Modifier</strong> reste à droite. Cette vue a aussi été vérifiée localement sur des largeurs de 1300 et 390 pixels. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/mqtt-client-v0.1.19" target="_blank" rel="noreferrer">Version 0.1.19</a></p><p>Depuis la version <strong>0.1.18</strong>, chaque ligne de la fenêtre d’un appareil distingue le <strong>nom</strong> sur la première ligne, l’<strong>identifiant de l’entité</strong> sur la deuxième, puis le <strong>type cible et le nombre d’attributs</strong> sur la troisième. Les noms et identifiants longs passent à la ligne ; l’état actuel reste à droite. Cette présentation est conservée après une modification de la sélection. Elle a été vérifiée localement sur des largeurs de 1300 et 390 pixels. La mise à jour conserve les paramètres, les identifiants de connexion et les transmissions sélectionnées. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/mqtt-client-v0.1.18" target="_blank" rel="noreferrer">Version 0.1.18</a></p><p>Le client MQTT transmet des appareils, des états et des attributs sélectionnés depuis Home Assistant vers un broker MQTT externe, comme par exemple l&#39;adaptateur MQTT d&#39;ioBroker. Au lieu de répliquer toutes les entités HA, vous sélectionnez vous-même les valeurs dont vous avez besoin. Le broker HA existant demeure en place. L&#39;application lit les données directement depuis HA ; il ne s&#39;agit pas d&#39;un pont entre brokers (bridge).</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/mqtt_client" target="_blank" rel="noreferrer">Code source et référence de configuration</a> · <a href="/en/projects/mqtt-client/">Documentation en anglais</a></p><h2 id="einrichtung-und-auswahl" tabindex="-1">Configuration et sélection <a class="header-anchor" href="#einrichtung-und-auswahl" aria-label="Permalink to &quot;Configuration et sélection {#einrichtung-und-auswahl}&quot;">​</a></h2><ol><li>Ajoutez <code>https://github.com/rockbaer2007/ugso-ha-mqtt-addons</code> depuis l&#39;App Store de Home Assistant. 2. Installer et lancer le <strong>client MQTT</strong> ; les architectures amd64 et aarch64 sont prises en charge.</li><li>Ouvrir l&#39;interface web et enregistrer l&#39;hôte, le port, l&#39;utilisateur et le mot de passe du broker externe. En l&#39;absence de TLS, le port par défaut est 1883.</li><li>Sélectionner un appareil sur la gauche. Dans la fenêtre qui s&#39;affiche, ses entités sont regroupées par catégories : commandes, capteurs, configuration et diagnostic. La fonction de recherche permet également de trouver des entités au sein d&#39;un appareil.</li><li>Sélectionner les valeurs et attributs souhaités. La case à cocher située à droite d&#39;une ligne de valeur permet de transférer l&#39;état ainsi que tous les attributs associés ; la sélection de l&#39;appareil permet quant à elle d&#39;inclure toutes les valeurs de celui-ci.</li></ol><p>Les modifications sont appliquées immédiatement. Aucun jeton d&#39;accès (access token) HA supplémentaire n&#39;est requis : l&#39;application utilise l&#39;accès « Supervisor » pour interagir avec l&#39;API HA Core. En cas d&#39;utilisation de plusieurs instances, veillez à employer des identifiants client (client IDs) et des préfixes de sujet (topic prefixes) distincts.</p><h2 id="weiterleitung-per-label" tabindex="-1">Transmettre les états avec une étiquette Home Assistant <a class="header-anchor" href="#weiterleitung-per-label" aria-label="Permalink to &quot;Transmettre les états avec une étiquette Home Assistant {#weiterleitung-per-label}&quot;">​</a></h2><p><img src="'+t+'" alt="Dialogue Home Assistant de création d’une étiquette"></p><p><em>Exemple dans Home Assistant : l’étiquette s’appelle « zu mqtt client ». Saisissez dans le client MQTT l’identifiant de l’étiquette que vous avez créée.</em></p><ol><li><strong>Créez l’étiquette :</strong> Dans Home Assistant, ouvrez <strong>Paramètres → Zones, étiquettes et zones géographiques → Étiquettes</strong>. Créez <strong>zu mqtt client</strong>, comme sur la capture.</li><li><strong>Relevez l’identifiant :</strong> Ouvrez <strong>Paramètres → Outils → Modèle</strong> (<strong>Outils de développement → Modèle</strong> dans les anciennes versions). Collez le modèle ci-dessous et copiez le résultat, par exemple <code>zu_mqtt_client</code>.</li><li><strong>Saisissez l’identifiant dans le client MQTT :</strong> Ouvrez <strong>MQTT-Client</strong> dans la barre latérale de Home Assistant. Dépliez <strong>Übertragung und TLS</strong> (Transmission et TLS). Collez le résultat dans <strong>HA-Label-ID für Zustandsweiterleitung</strong>, juste sous <strong>Topic-Präfix</strong>, puis cliquez sur <strong>Speichern und verbinden</strong> (Enregistrer et connecter).</li><li><strong>Attribuez l’étiquette :</strong> Ouvrez <strong>Paramètres → Appareils et services → Entités</strong>, sélectionnez l’entité et ouvrez ses paramètres avec la roue dentée. Choisissez <strong>Ajouter une étiquette → zu mqtt client</strong>, puis cliquez sur <strong>Mettre à jour</strong>.</li></ol><div class="language-jinja vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">jinja</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">{{ </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">label_id</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;zu mqtt client&quot;</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">) }}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><a href="https://www.home-assistant.io/template-functions/label_id/" target="_blank" rel="noreferrer">Home Assistant · label_id</a></p><p>Le client vérifie les associations selon l’intervalle d’interrogation configuré. L’étiquette transmet l’état et les métadonnées standard et active les commandes prises en charge. Les autres attributs restent sélectionnables manuellement. Le retrait de l’étiquette arrête la transmission et les commandes automatiques. Les entités sélectionnées manuellement restent actives. Le nettoyage des topics persistants permet de supprimer la dernière valeur MQTT mémorisée si nécessaire.</p><p>Essai effectué sur Home Assistant <code>.177</code> avec un broker MQTT séparé. Après l’ajout de l’étiquette, le broker a reçu <code>off</code> et <code>on</code>. Après son retrait, le changement d’état suivant n’a plus été envoyé. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/mqtt-client-v0.1.17" target="_blank" rel="noreferrer">Release 0.1.17</a></p><h2 id="live-ubertragung-und-status" tabindex="-1">Transmission en temps réel et état <a class="header-anchor" href="#live-ubertragung-und-status" aria-label="Permalink to &quot;Transmission en temps réel et état {#live-ubertragung-und-status}&quot;">​</a></h2><p>Après le chargement initial de l&#39;état complet, l&#39;application traite les changements d&#39;état de HA en temps réel via WebSocket. Si la connexion à HA est rétablie, l&#39;état initial est rechargé ; si la connexion MQTT est rétablie, toutes les valeurs sélectionnées sont retransmises.</p><p>En cas de défaillance de la connexion en temps réel, le mécanisme d&#39;interrogation (polling) précédent prend le relais — configuré par défaut sur un intervalle de cinq secondes, mais ajustable via <code>poll_interval</code> (de 1 à 300 secondes). Les changements survenus pendant une interruption ou entre deux intervalles d&#39;interrogation ne peuvent pas être reconstitués a posteriori. Une saturation de la file d&#39;attente des événements est signalée et déclenche une resynchronisation.</p><p>L&#39;état permet de distinguer la connexion MQTT de l&#39;accessibilité de HA ; il affiche le mode actif (temps réel/interrogation), l&#39;heure de la dernière synchronisation, la date de la dernière publication, le nombre total de publications, ainsi que tout type d&#39;erreur ayant été résolu. Les identifiants d&#39;accès et le contenu des messages (payloads) ne sont pas affichés.</p><table tabindex="0"><thead><tr><th>Sujet MQTT</th><th>Contenu</th></tr></thead><tbody><tr><td><code>&lt;topic_prefix&gt;/&lt;device&gt;/&lt;value&gt;/state</code></td><td>État sous forme textuelle</td></tr><tr><td><code>&lt;topic_prefix&gt;/&lt;device&gt;/&lt;value&gt;/attribute/&lt;attribute&gt;</code></td><td>Attribut sélectionné</td></tr><tr><td><code>&lt;topic_prefix&gt;/&lt;device&gt;/&lt;value&gt;/set</code></td><td>Canal de retour pour les commandes de contrôle prises en charge</td></tr><tr><td><code>&lt;topic_prefix&gt;/availability</code></td><td><code>online</code> en cas de synchronisation HA réussie ; sinon <code>offline</code></td></tr></tbody></table><p>Le préfixe par défaut est <code>ha_external</code>. Les états et les attributs sont publiés avec un niveau de QoS 1 et le drapeau « retain » (conservation) ; aucune configuration de découverte MQTT (MQTT discovery) n&#39;est générée. Lors de la connexion initiale, les états et les attributs sont envoyés avant les canaux de retour d&#39;information <code>/set</code>, avec un intervalle par défaut de 50 ms entre chaque publication. Les messages <code>unknown</code> et <code>unavailable</code> sont transmis tels quels ; les entités inexistantes renvoient <code>unavailable</code>.</p><h2 id="steuerbefehle-zuruck-an-ha" tabindex="-1">Commandes de contrôle vers HA <a class="header-anchor" href="#steuerbefehle-zuruck-an-ha" aria-label="Permalink to &quot;Commandes de contrôle vers HA {#steuerbefehle-zuruck-an-ha}&quot;">​</a></h2><p>Les canaux de retour d&#39;information sont automatiquement activés pour les entités contrôlables sélectionnées. Les capteurs restent en mode « sortie uniquement ». Envoyez les commandes vers le sujet (<code>topic</code>) <code>/set</code> correspondant, <strong>sans utiliser l&#39;indicateur « retain »</strong>.</p><table tabindex="0"><thead><tr><th>Entité</th><th>Données (Payload)</th></tr></thead><tbody><tr><td>Entité commutable</td><td><code>ON</code> ou <code>OFF</code></td></tr><tr><td><code>number</code>, <code>input_number</code></td><td>Valeur numérique</td></tr><tr><td><code>select</code>, <code>input_select</code></td><td>Nom d&#39;une option disponible</td></tr><tr><td><code>text</code>, <code>input_text</code></td><td>Texte</td></tr><tr><td><code>button</code>, <code>input_button</code></td><td><code>PRESS</code></td></tr><tr><td><code>cover</code></td><td><code>OPEN</code>, <code>CLOSE</code>, <code>STOP</code> ou <code>{&quot;position&quot;:45}</code></td></tr><tr><td><code>light</code></td><td><code>{&quot;brightness_pct&quot;:75}</code></td></tr><tr><td><code>fan</code></td><td><code>{&quot;percentage&quot;:50}</code></td></tr></tbody></table><p>Les commandes JSON n&#39;autorisent que le champ spécifié, accompagné d&#39;une valeur numérique comprise entre 0 et 100. L&#39;appareil HA (Home Assistant) doit prendre en charge cette fonctionnalité. Les anciens identifiants d&#39;entité (Entity IDs), tels que <code>ha_external/switch.plug/set</code>, restent valides. Les messages avec l&#39;indicateur « retain » (persistant), les commandes obsolètes et les contenus non valides sont ignorés ; l&#39;exécution d&#39;actions HA arbitraires n&#39;est pas prévue.</p><h2 id="veraltete-retain-topics-entfernen" tabindex="-1">Suppression des « topics » persistants (retain topics) obsolètes <a class="header-anchor" href="#veraltete-retain-topics-entfernen" aria-label="Permalink to &quot;Suppression des « topics » persistants (retain topics) obsolètes {#veraltete-retain-topics-entfernen}&quot;">​</a></h2><p>La fonction <strong>Vérifier les « topics » persistants obsolètes</strong> affiche les « topics » enregistrés qui ne sont plus utilisés en raison de modifications apportées à la sélection, aux préfixes ou aux noms des appareils. Sélectionnez les « topics » concernés et confirmez leur suppression ; un maximum de 100 éléments peut être traité par opération.</p><p>L&#39;application supprime uniquement les publications qu&#39;elle a elle-même effectuées et confirmées avec succès sur le broker actuellement configuré. Les « topics » actifs ainsi que ceux créés par d&#39;autres sources restent intacts. L&#39;inventaire est conservé de manière permanente sous <code>/data/mqtt-topics.json</code>. En cas d&#39;échec de la suppression, l&#39;élément est conservé pour une nouvelle tentative ultérieure. Il n&#39;existe <strong>pas de nettoyage automatique</strong>. Les anciens « topics » non répertoriés, créés avant cette mise à jour, doivent être supprimés directement sur le broker.</p><h2 id="einstellungen-sichern-und-wiederherstellen" tabindex="-1">Sauvegarde et restauration des paramètres <a class="header-anchor" href="#einstellungen-sichern-und-wiederherstellen" aria-label="Permalink to &quot;Sauvegarde et restauration des paramètres {#einstellungen-sichern-und-wiederherstellen}&quot;">​</a></h2><p>La fonction <strong>Sauvegarder les paramètres</strong> permet de télécharger un fichier JSON contenant les paramètres du broker, l&#39;identifiant client (Client ID), le préfixe des « topics », la sélection, l&#39;intervalle d&#39;interrogation, l&#39;espacement des publications et l&#39;autorité de certification (CA) personnalisée. La fonction <strong>Ouvrir une sauvegarde</strong> vérifie le contenu du fichier et demande une confirmation avant de procéder au remplacement des paramètres actuels.</p><p>Le fichier ne contient <strong>ni mot de passe MQTT, ni certificat client, ni clé privée, ni jeton (token) HA</strong>. Il n&#39;est pas chiffré. Si vous utilisez le même broker, les identifiants et le certificat/la clé client stockés localement sont conservés. Si vous changez de broker, ces informations doivent être saisies à nouveau. Les messages « retained » (conservés) ne sont pas inclus ; cette procédure ne remplace pas une sauvegarde complète de l&#39;application HA.</p><h2 id="tls-mit-eigenen-zertifikaten" tabindex="-1">TLS avec certificats personnalisés <a class="header-anchor" href="#tls-mit-eigenen-zertifikaten" aria-label="Permalink to &quot;TLS avec certificats personnalisés {#tls-mit-eigenen-zertifikaten}&quot;">​</a></h2><p>Dans la section <strong>Transmission et TLS</strong>, vous pouvez charger des fichiers PEM (contenant une autorité de certification, un certificat client et une clé privée) ou coller leur contenu textuel. Le certificat et la clé doivent être fournis ensemble. Le port TLS dépend du broker utilisé ; il s&#39;agit souvent du port 8883.</p><p>Le certificat du serveur et le nom d&#39;hôte sont systématiquement vérifiés, soit via les autorités de confiance du système, soit via une autorité de certification (CA) personnalisée. Si les champs de données sensibles sont laissés vides, les valeurs précédemment enregistrées sont conservées. Pour les supprimer, cochez l&#39;option spécifique <strong>Supprimer les certificats et clés TLS enregistrés</strong> et enregistrez vos modifications. Toute configuration TLS invalide sera rejetée lors de la tentative de modification des paramètres.</p><h2 id="update-und-kompatibilitat" tabindex="-1">Mise à jour et compatibilité <a class="header-anchor" href="#update-und-kompatibilitat" aria-label="Permalink to &quot;Mise à jour et compatibilité {#update-und-kompatibilitat}&quot;">​</a></h2><p>Les paramètres existants issus de 0.1.15 restent valides : les identifiants du broker, la sélection des appareils/attributs, l&#39;ID client, le préfixe des sujets (topics), l&#39;intervalle d&#39;interrogation et l&#39;intervalle de publication ne sont pas modifiés au démarrage. La configuration TLS est conservée ; les nouveaux champs relatifs aux certificats sont vides par défaut. Les données conservées (« retained data ») ne sont pas supprimées lors de la mise à jour.</p><p>La version 0.1.16 a été validée via des tests backend, un broker MQTT, un point de terminaison WebSocket, TLS avec certificat client, une interface web et un déploiement Docker. L&#39;installation effective dans Home Assistant (HA) ainsi que les fonctionnalités prises en charge doivent être vérifiées dans votre propre environnement.</p>',76)])])}const h=s(i,[["render",o]]);export{v as __pageData,h as default};
